/*
 * headless_lang_verbs.c - Lang processor verb implementations
 *
 * Originally generated by tools/kernelverbs_parser/generate_processor_stubs.py,
 * now contains dispatcher pattern forwarding to real implementations.
 *
 * DO NOT regenerate - this file contains production implementations.
 *
 * Implementation pattern:
 * - Uses dispatcher pattern forwarding to existing langverbs.c functions
 * - Most verbs forward to: langscripterrorfunc, newvaluefunc, langdeletefunc, etc.
 * - Some verbs still stubbed (marked "not implemented")
 * - Allows lang.* verbs to work in headless mode by delegating to core lang layer
 */

