            if (bserror) copystring(BIGSTRING("\036not supported on this platform"), bserror);
            return false;
        case lanv_transactionevent:
            /* Verb: lang.transactionevent - AppleEvent verb not supported on this platform (Issue #284) @IMPLEMENTED */
            if (bserror) copystring(BIGSTRING("\036not supported on this platform"), bserror);
